package api

// OpenAPI 3.1 document for every route. Operations are hand-listed in `ops`
// (summary, tag, auth, request/response types); JSON Schemas are generated by
// reflection from the real Go types, so field names never drift. A test
// (openapi_test.go) walks the chi router and fails if a route is missing here.

import (
	"github.com/go-chi/chi/v5"
	"net/http"
	"reflect"
	"strconv"
	"strings"
	"sync"
	"time"

	"boxaz/core/internal/agentkit"
	"boxaz/core/internal/boxyaml"
	"boxaz/core/internal/manager"
	"boxaz/core/internal/model"
	"boxaz/core/internal/proto"
	"boxaz/core/internal/provider"
)

type param struct {
	Name, In, Type, Desc string
	Required             bool
}

type op struct {
	Method, Path, Summary, Tag string
	NoAuth                     bool
	Req                        any    // request body type (nil = none)
	Resp                       any    // response type (nil = generic object)
	List                       bool   // response is {items:[Resp], next_cursor}
	Status                     int    // success status (default 200)
	Content                    string // non-JSON response content type
	Params                     []param
	Desc                       string
}

var idP = param{"id", "path", "string", "Box id (box_…) or slug", true}

func qp(name, typ, desc string) param { return param{name, "query", typ, desc, false} }

type ok struct {
	OK bool `json:"ok"`
}

type healthResp struct {
	OK         bool              `json:"ok"`
	Version    string            `json:"version"`
	Components map[string]string `json:"components"`
}

type fileRead struct {
	Path       string        `json:"path"`
	Type       string        `json:"type"`
	Content    string        `json:"content,omitempty"`
	TotalLines int           `json:"total_lines,omitempty"`
	Entries    []proto.Entry `json:"entries,omitempty"`
}

type fileWrite struct {
	Path    string `json:"path"`
	Content string `json:"content"`
}

type grepReq struct {
	Pattern string `json:"pattern"`
	Path    string `json:"path,omitempty"`
}

type yamlReq struct {
	YAML string `json:"yaml"`
}

type validateResp struct {
	OK     bool                `json:"ok"`
	Errors []boxyaml.LineError `json:"errors"`
}

type tokenReq struct {
	Token string `json:"token"`
}

type hostReq struct {
	Provider string `json:"provider"`
	SKU      string `json:"sku"`
	Region   string `json:"region"`
	Billing  string `json:"billing,omitempty"`
}

type rotateReq struct {
	Value  string   `json:"value"`
	Agents []string `json:"agents,omitempty"`
}

type stopReq struct {
	Confirm string `json:"confirm"`
}

type jobID struct {
	JobID string `json:"job_id"`
}

type boxYAMLResp struct {
	BoxID  string `json:"box_id"`
	YAML   string `json:"yaml"`
	Source string `json:"source"`
}

type errEnvelope struct {
	Error model.APIError `json:"error"`
}

